mapper.select:
/* PlatformLocationMapper.selectOperatorMbl */
SELECT
    U.MBL_NO_ENC    AS mblNoEnc
    , U.MBL_NO_HMAC AS mblNoHmac
FROM TB_USER U
WHERE U.CMPNY_CD = #{cmpnyCd}
  AND U.USER_CD  = #{userCd}

mapper.insert:
/* PlatformLocationMapper.insertPlatformSmsAuth */
INSERT INTO TB_SMS_AUTH_CODE (
    MBL_NO_ENC
    , MBL_NO_HMAC
    , AUTH_CD
    , PURPOSE_CD
    , EXPIRED_AT
    , INSERT_NO
)
VALUES (
    #{mblNoEnc}
    , #{mblNoHmac}
    , #{certNo}
    , 'PLATFORM_LOCATION'
    , DATE_ADD(NOW(), INTERVAL 1 MINUTE)
    , #{gvUserCd}
)

mapper.update:
/* PlatformLocationMapper.updatePlatformSmsVerified */
UPDATE TB_SMS_AUTH_CODE
SET
    VERIFIED_YN   = 'Y'
    , UPDATE_NO   = #{gvUserCd}
    , UPDATE_DATE = NOW()
WHERE 1=1
  AND SMS_ID      = #{smsId}
  AND MBL_NO_HMAC = #{mblNoHmac}
  AND AUTH_CD     = #{certNo}
  AND PURPOSE_CD  = 'PLATFORM_LOCATION'
  AND EXPIRED_AT  >=  NOW()
  AND VERIFIED_YN = 'N'
  AND FAIL_CNT  <  5

mapper.insert:
/* PlatformLocationMapper.insertLocationAccessLog */
INSERT INTO TB_LOCATION_ACCESS_LOG (
    ACCESSOR_USER_CD
    , ACCESS_DTIME
    , TARGET_CMPNY_CD
    , TARGET_SITE_CD
    , TARGET_DATE
    , SMS_AUTH_ID
    , SMS_VERIFIED_AT
    , RESULT_CNT
    , CLIENT_IP
    , REMOTE_ADDR
    , INSERT_NO
    , INSERT_DATE
)
VALUES (
    #{accessorUserCd}
    , NOW()
    , #{targetCmpnyCd}
    , #{targetSiteCd}
    , #{targetDate}
    , #{smsAuthId}
    , #{smsVerifiedAt}
    , #{resultCnt}
    , #{clientIp}
    , #{remoteAddr}
    , #{accessorUserCd}
    , NOW()
)
